from taf.internal.impact_radar import log_radar

from taf.hw.rf_attenuator.available_devices import SupportedAttenuatorVendors


class AttenuatorFactory(object):

    @staticmethod
    def _create(vendor, ip, port, model=None, version=None, min_attenuation=None, max_attenuation=None, **kwargs):
        log_radar(
            "Tracking the usage of RF attenuator devices",
            vendor=vendor,
            model=model,
            version=version,
        )

        vendors = SupportedAttenuatorVendors()
        attenuator_device = vendors[vendor][model][version]
        return attenuator_device(ip=ip, port=port, min_attenuation=min_attenuation,
                                 max_attenuation=max_attenuation, **kwargs)

    @classmethod
    def create(cls, attenuator=None, min_attenuation=None, max_attenuation=None, **kwargs):
        """
        Creates attenuator object.

        If the `attenuator` is not None we assume it is a `taf.config.testline` Attenuator instance.
        User will get the specified attenuator device.

        If the `attenuator` is None, we get the attenuator parameters from kwargs.

        Raises DeviceNotSupported.
        """
        vendor = attenuator.vendor if attenuator is not None else kwargs['vendor']
        model = attenuator.model if attenuator is not None else kwargs.get('model', None)
        version = attenuator.version if attenuator is not None else kwargs.get('version', None)
        min_attenuation = int(min_attenuation) if min_attenuation is not None else None
        max_attenuation = int(max_attenuation) if max_attenuation is not None else None
        ip = attenuator.ip_addr if attenuator is not None else kwargs['ip_addr']
        port = attenuator.port if attenuator is not None else kwargs['port']
        params = {'vendor': vendor, 'model': model, 'version': version, 'min_attenuation': min_attenuation,
                  'max_attenuation': max_attenuation, 'ip': ip, 'port': port}
        if hasattr(attenuator, 'mode'):
            params['mode'] = attenuator.mode
        elif 'mode' in kwargs:
            params['mode'] = kwargs['mode']
        return cls._create(**params)
